import { RULES, type Rule } from "../rules/index.js";

const CATEGORY_TITLE: Record<Rule["category"], string> = {
  "tool-poisoning": "Tool poisoning",
  shadowing: "Shadowing and name collisions",
  "excessive-permissions": "Excessive permissions",
  secrets: "Secrets",
  transport: "Transport",
  runtime: "Runtime (--probe)",
};

/** docs/rules.md, generated from the rule definitions so the two cannot drift. */
export function rulesMarkdown(): string {
  const out: string[] = [
    "# mcp-guard rules",
    "",
    "<!-- Generated by `npm run docs:rules` from src/core/rules. Do not edit by hand. -->",
    "",
    "Every rule is deterministic: the same inventory always produces the same findings. Static rules read the inventory only; runtime rules need `--probe`. The optional LLM judge annotates MCPG-005 findings and never changes a severity or the exit code.",
    "",
    "| ID | Severity | Category | Mode | Rule |",
    "| --- | --- | --- | --- | --- |",
    ...RULES.map(
      (r) =>
        `| [${r.id}](#${r.id.toLowerCase()}) | ${r.severity} | ${r.category} | ${r.mode} | ${r.title} |`,
    ),
    "",
  ];
  for (const [category, title] of Object.entries(CATEGORY_TITLE)) {
    const rules = RULES.filter((r) => r.category === category);
    if (rules.length === 0) continue;
    out.push(`## ${title}`, "");
    for (const r of rules) {
      out.push(
        `<a id="${r.id.toLowerCase()}"></a>`,
        "",
        `### ${r.id} ${r.title}`,
        "",
        `**Severity:** ${r.severity} \u00B7 **Mode:** ${r.mode} \u00B7 **SARIF name:** \`${r.name}\``,
        "",
        r.description,
        "",
        "Bad:",
        "",
        "```text",
        r.bad,
        "```",
        "",
        "Good:",
        "",
        "```text",
        r.good,
        "```",
        "",
        `**Remediation.** ${r.remediation}`,
        "",
        "References:",
        "",
        ...r.references.map((ref) => `- [${ref.title}](${ref.url})`),
        "",
      );
    }
  }
  return `${out.join("\n").trimEnd()}\n`;
}
